"""Screen 05 full reference match — whole-frame and per-region comparison of a REAL game capture with the APPROVED image.
Masks: qa/pilot05/full_reference_match/masks/region_index.png (tools/match05/regions.py; every pixel in exactly one region).
Per region and for the whole frame: pixels, mean |dRGB| (0-255, mean over channels), share within 10 / 20 levels,
luminance SSIM (Gaussian sigma 1.5), mean signed RGB (capture - approved: colour contamination).
These are pixel statistics, NOT a universal "visual similarity percentage"; each number is reported next to its mask.
usage: python3 -I tools/match05/metrics.py <capture.png> <out_prefix> [--proof <before.png>]
  -> <out_prefix>REGION_METRICS.json, <out_prefix>FULL_FRAME_METRICS.json
  --proof also writes 04_DIFFERENCE.png and 05_OVERLAY.png next to the prefix"""
import json, sys, os
import numpy as np
from PIL import Image, ImageDraw
from scipy.ndimage import gaussian_filter
M = "qa/pilot05/full_reference_match/masks"
cap, pre = sys.argv[1], sys.argv[2]
ap = np.asarray(Image.open("references/05_flow_into_the_current.png").convert("RGB"), float)
c = np.asarray(Image.open(cap).convert("RGB"), float)
idx = np.asarray(Image.open(f"{M}/region_index.png"))
names = {v["id"]: k for k, v in json.load(open(f"{M}/regions.json"))["regions"].items()}
d = np.abs(c - ap).mean(-1)
def ssim_map(a, b):
    la, lb = (a * [0.2126, 0.7152, 0.0722]).sum(-1), (b * [0.2126, 0.7152, 0.0722]).sum(-1)
    s = 1.5; C1, C2 = (0.01 * 255) ** 2, (0.03 * 255) ** 2
    ma, mb = gaussian_filter(la, s), gaussian_filter(lb, s)
    va, vb = gaussian_filter(la * la, s) - ma * ma, gaussian_filter(lb * lb, s) - mb * mb
    cab = gaussian_filter(la * lb, s) - ma * mb
    return ((2 * ma * mb + C1) * (2 * cab + C2)) / ((ma * ma + mb * mb + C1) * (va + vb + C2))
sm = ssim_map(ap, c)
def st(m):
    return dict(px=int(m.sum()), share_of_frame=round(float(m.mean()), 4), mean_abs=round(float(d[m].mean()), 2),
                within_10=round(float((d[m] <= 10).mean()), 4), within_20=round(float((d[m] <= 20).mean()), 4),
                ssim_lum=round(float(sm[m].mean()), 4), mean_signed_rgb=[round(float(v), 1) for v in (c[m] - ap[m]).mean(0)])
reg = {names[i]: st(idx == i) for i in sorted(names)}
full = dict(capture=cap, whole_frame=st(np.ones_like(idx, bool)),
            note="whole frame = all 864x1536 pixels, nothing excluded; pixel statistics, not a perceptual score",
            mse=round(float(((c - ap) ** 2).mean()), 1), psnr_db=round(float(10 * np.log10(255 ** 2 / ((c - ap) ** 2).mean())), 2))
json.dump(dict(capture=cap, regions=reg), open(pre + "REGION_METRICS.json", "w"), indent=1)
json.dump(full, open(pre + "FULL_FRAME_METRICS.json", "w"), indent=1)
print("FULL", full["whole_frame"])
for k, v in reg.items(): print(f"{k:28s} px {v['px']:7d}  mean {v['mean_abs']:6.2f}  <=10 {v['within_10']:.3f}  <=20 {v['within_20']:.3f}  ssim {v['ssim_lum']:.3f}  signed {v['mean_signed_rgb']}")
if "--proof" in sys.argv:
    outd = os.path.dirname(pre) or "."
    # 04 difference: grey approved underlay; green <= 10, yellow 10-20, orange 20-40, red > 40 levels
    g = np.stack([ap.mean(-1)] * 3, -1) * 0.35
    col = np.zeros_like(g)
    col[d <= 10] = (40, 200, 70); col[(d > 10) & (d <= 20)] = (235, 220, 40); col[(d > 20) & (d <= 40)] = (245, 140, 30); col[d > 40] = (235, 40, 40)
    o = (g + 0.65 * col).clip(0, 255).astype(np.uint8)
    im = Image.fromarray(o); dr = ImageDraw.Draw(im)
    dr.rectangle([0, 1440, 863, 1535], fill=(0, 0, 0))
    leg = [((40, 200, 70), "within 10 levels of APPROVED"), ((235, 220, 40), "10-20 levels"), ((245, 140, 30), "20-40 levels"), ((235, 40, 40), "more than 40 levels")]
    for i, (cc, t) in enumerate(leg):
        x = 12 + (i % 2) * 430; y = 1450 + (i // 2) * 40
        dr.rectangle([x, y, x + 26, y + 26], fill=cc); dr.text((x + 36, y + 7), t, fill=(255, 255, 255))
    dr.text((12, 1522), "IMAGE 4 - DIFFERENCE: NEW vs APPROVED, mean |dRGB| per pixel (0-255)", fill=(255, 255, 255))
    im.save(os.path.join(outd, "04_DIFFERENCE.png"))
    Image.fromarray(((ap + c) / 2).astype(np.uint8)).save(os.path.join(outd, "05_OVERLAY.png"))
/**
 * Rider splash (ref 05: a V of fine white/cyan droplet streaks thrown BACK and OUTWARD from Benny's
 * base, one fan per flank, frothy lace at the roots, clear glossy water straight behind him).
 *
 * Wave 4 rebuild. The wave-3 fan was one continuous mesh sheet per flank (16 × 8 quads) whose straight
 * borders and long noise jets rendered as translucent white wedges / spikes beside Benny. Now the fan is
 * made of many INDEPENDENT streaks: each instance is a short, thin, camera-facing ribbon that rides along
 * its own ballistic jet path (rooted on the waterline circle under the fur, aimed back-outward, arcing up
 * and falling back to the water), tapers at its tail and breaks into droplet beads late in its flight.
 * A quarter of the instances are wider, short-lived "froth" puffs of white lace near the roots. Nothing
 * has a hard outline, so the fan reads as spray, not geometry. The ballistic droplets in spray.ts
 * (index.ts `wake()`) share the same jet layout (FAN).
 *
 * One instanced draw (2 × N streaks of 6 segments), shaped and animated entirely in the vertex shader
 * (no per-frame CPU work besides placement), placed every frame at the water surface under Benny's real
 * (lifted) body centre. Hidden automatically when wake() stops being called (intro / outro).
 */
import * as THREE from 'three';
import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
import { WATER05 } from './waterRibbon'; // Screen 05 water test W10 (?water05=1): thinner, wider splash threads

/**
 * Jet layout shared with the spray droplets (index.ts): across a = 0 (outer, most sideways jet) … 1
 * (inner, most backward jet). Angles in radians measured from straight back (towards the chase camera).
 * Ref 05 at the live camera (≈185 px per lateral unit, ≈100 px per unit back at Benny): the outer jets
 * leave at ≈32° below the horizontal on screen (≈41° from back in the world), the inner ones at ≈67°
 * (≈13° from back).
 */
export const FAN = {
  /** root angle on the root circle (ref 05 roots ≈(330, 1180) / (540, 1170): ≈0.5 u out, 0.3 u back) */
  root0: 1.25,
  root1: 0.72,
  /** jet direction */
  dir0: 0.78,
  dir1: 0.1,
  /** jets start at the fur skirt, not under the body: root circle radius ≥ this (units) */
  rootMin: 0.56,
} as const;

const SEG = 6;

const VERT = /* glsl */ `
attribute vec2 aUV;      // x: 0 tail .. 1 head (along the streak), y: -1..1 across
attribute vec4 aJet;     // x: side (-1 / 1), y: across a (0 outer .. 1 inner), z: phase, w: seed
uniform float uTime;
uniform float uR;        // waterline radius of Benny's body (units): jet roots sit on this circle
uniform float uLen;      // max jet length (units)
uniform float uH;        // max arc height (units)
uniform float uStrength; // 0..1
varying vec2 vUV;
varying float vTau;
varying float vSeed;
varying float vFroth;
#include <fog_pars_vertex>
float hs(float n) { return fract(sin(n * 91.345 + 3.17) * 43758.5453); }
vec3 jetPos(float tau, float side, float a, float seed, float froth) {
  float thR = mix(${FAN.root0.toFixed(3)}, ${FAN.root1.toFixed(3)}, a) + (hs(seed * 3.1) - 0.5) * 0.14;
  // jets curl slightly outward as they fly (ref: the outer streaks bend towards the banks)
  float phi = mix(${FAN.dir0.toFixed(3)}, ${FAN.dir1.toFixed(3)}, a) + (hs(seed * 5.7) - 0.5) * 0.3 + 0.18 * tau;
  vec2 root = vec2(sin(thR), cos(thR)) * max(uR, ${FAN.rootMin.toFixed(3)}) * (0.9 + 0.12 * hs(seed * 2.3));
  float len = uLen * (0.6 + 0.4 * hs(seed * 7.3)) * (0.85 + 0.15 * sin(3.14159 * a)) * (0.55 + 0.45 * uStrength);
  len *= mix(1.0, 0.5, froth);
  vec2 q = root + vec2(sin(phi), cos(phi)) * tau * len;
  // most jets skim low over the water (ref: a flat fan), one in five is flung up as a high arc
  float tall = step(0.8, hs(seed * 29.3));
  float H = uH * mix(0.22 + 0.4 * hs(seed * 9.1), 1.0 + 0.35 * hs(seed * 9.1), tall) * (1.1 - 0.4 * a) * uStrength * mix(1.0, 0.4, froth);
  float tp = pow(max(tau, 0.0), 0.7);
  float y = H * 4.0 * tp * (1.0 - tp) - 0.012;
  return vec3(side * q.x, y, q.y);
}
void main() {
  float side = aJet.x;
  float a = aJet.y;
  float seed = aJet.w;
  float froth = step(0.6, hs(seed * 17.9));
  // life cycle: the streak's head runs from the root (tau 0) to the landing point (tau 1)
  float rate = mix(1.5, 2.5, hs(seed * 11.3)) * mix(1.0, 1.4, froth);
  float cyc = fract(aJet.z + uTime * rate);
  float tl = mix(0.22, 0.5, hs(seed * 13.7)) * mix(1.0, 0.6, froth);
  float head = cyc * (1.0 + tl);
  float tau = clamp(head - (1.0 - aUV.x) * tl, 0.0, 1.0);
  vec3 p = jetPos(tau, side, a, seed, froth);
  vec3 tg = jetPos(min(tau + 0.03, 1.0), side, a, seed, froth) - jetPos(max(tau - 0.03, 0.0), side, a, seed, froth);
  vec4 mvPosition = modelViewMatrix * vec4(p, 1.0);
  vec2 tv = (modelViewMatrix * vec4(tg, 0.0)).xy;
  float tl2 = length(tv);
  vec2 nrm = tl2 > 1e-5 ? vec2(-tv.y, tv.x) / tl2 : vec2(0.0, 1.0);
  // thin jets (≈2–5 px wide at Benny's distance), wider soft froth; tapered tail, round head
  float w = mix(mix(0.011, 0.024, hs(seed * 19.1)), mix(0.05, 0.095, hs(seed * 23.3)), froth);
  w *= mix(0.35, 1.0, smoothstep(0.0, 0.7, aUV.x)) * (0.7 + 0.3 * uStrength);
  mvPosition.xy += nrm * aUV.y * w;
  vUV = aUV;
  vTau = tau;
  vSeed = seed;
  vFroth = froth;
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}
`;

const FRAG = /* glsl */ `
uniform float uStrength;
varying vec2 vUV;
varying float vTau;
varying float vSeed;
varying float vFroth;
#include <fog_pars_fragment>
${NOISE_GLSL}
void main() {
  float ac = abs(vUV.y);
  float across = 1.0 - smoothstep(0.25, 1.0, ac);
  float along = smoothstep(0.0, 0.75, vUV.x);
  // fade in as it leaves the water under the fur, fade out as it falls back in
  float life = smoothstep(0.0, 0.1, vTau) * (1.0 - smoothstep(0.78, 1.0, vTau));
  // late in flight the jet breaks into droplet beads
  float bead = 1.0 - smoothstep(0.18, 0.42, abs(fract(vUV.x * 3.0 + vSeed * 7.0) - 0.5));
  float breakup = smoothstep(0.42, 0.75, vTau);
  float jet = across * along * mix(1.0, bead, breakup);
  // froth: bubbly white lace (open cells), soft all round
  float lc = cells(vec2(vUV.x * 2.6 + vSeed * 31.0, vUV.y * 1.3 + vSeed * 17.0));
  float lace = (1.0 - smoothstep(0.25, 0.55, lc)) * (1.0 - smoothstep(0.5, 1.0, ac)) * smoothstep(0.0, 0.35, vUV.x);
  float k = mix(jet, lace, vFroth);
  float alpha = k * life * uStrength * mix(0.95, 0.75, vFroth);
  if (alpha < 0.015) discard;
  // white core, cyan translucent edges; froth slightly lavender in its crevices
  vec3 cyan = vec3(0.42, 0.86, 1.0);
  vec3 white = vec3(1.12, 1.14, 1.18);
  vec3 col = mix(cyan, white, mix(smoothstep(0.1, 0.9, across) * (0.55 + 0.45 * along), 0.85, vFroth));
  col = mix(col, vec3(0.86, 0.84, 1.06), vFroth * smoothstep(0.15, 0.4, lc) * 0.35);
  gl_FragColor = vec4(col, alpha);
  ${FRAG_TAIL}
}
`;

export interface RiderSplash {
  mesh: THREE.Mesh;
  uniforms: Record<string, THREE.IUniform>;
  /** place on the water under Benny: waterline centre + frame + body radius at the waterline */
  place(center: THREE.Vector3, forward: THREE.Vector3, up: THREE.Vector3, radius: number, strength: number): void;
  update(time: number, dt: number): void;
}

export function createRiderSplash(quality: 'high' | 'low'): RiderSplash {
  const perSide = quality === 'high' ? 150 : 60;
  // base strip: SEG segments along, 2 vertices across
  const uvs = new Float32Array((SEG + 1) * 2 * 2);
  for (let i = 0; i <= SEG; i++) {
    uvs.set([i / SEG, -1, i / SEG, 1], i * 4);
  }
  const idx: number[] = [];
  for (let i = 0; i < SEG; i++) {
    const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
    idx.push(a, c, b, b, c, d);
  }
  const geo = new THREE.InstancedBufferGeometry();
  geo.setAttribute('aUV', new THREE.BufferAttribute(uvs, 2));
  // dummy position attribute (positions are generated in the vertex shader)
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array((SEG + 1) * 2 * 3), 3));
  geo.setIndex(idx);
  const n = perSide * 2;
  const jet = new Float32Array(n * 4);
  // deterministic layout: stratified across the fan, golden-ratio phases (no clumping in a frozen frame)
  let k = 0;
  for (const side of [-1, 1]) {
    for (let i = 0; i < perSide; i++) {
      const h = (x: number) => { const v = Math.sin(x * 127.1 + side * 311.7) * 43758.5453; return v - Math.floor(v); };
      const a = Math.min(1, Math.max(0, (i + h(i * 1.7)) / perSide));
      jet[k++] = side;
      // denser towards the middle of the fan, thinner at both borders
      jet[k++] = 0.5 + (a - 0.5) * (0.75 + 0.25 * Math.abs(a - 0.5) * 2);
      jet[k++] = (i * 0.6180339 + h(i * 3.3) * 0.25) % 1;
      jet[k++] = h(i * 5.1 + 0.37);
    }
  }
  geo.setAttribute('aJet', new THREE.InstancedBufferAttribute(jet, 4));
  geo.instanceCount = n;
  const uniforms = withFog({ uTime: { value: 0 }, uR: { value: 0.45 }, uLen: { value: 1.25 }, uH: { value: 0.34 }, uStrength: { value: 0 } });
  const mat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: VERT,
    fragmentShader: FRAG,
    fog: true,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.name = 'rider_splash';
  mesh.frustumCulled = false;
  mesh.renderOrder = 3;
  mesh.visible = false;
  const basis = new THREE.Matrix4();
  const back = new THREE.Vector3();
  const side = new THREE.Vector3();
  let target = 0;
  let fed = false;
  return {
    mesh,
    uniforms,
    place(center, forward, up, radius, strength) {
      back.copy(forward).multiplyScalar(-1);
      side.crossVectors(up, back).normalize(); // x × y = z  →  (side, up, back) right-handed
      basis.makeBasis(side, up, back);
      mesh.quaternion.setFromRotationMatrix(basis);
      mesh.position.copy(center);
      uniforms.uR.value = radius;
      target = strength;
      fed = true;
    },
    update(time, dt) {
      uniforms.uTime.value = time;
      if (!fed) target = 0;
      fed = false;
      const s = uniforms.uStrength.value as number;
      const v = dt > 0 ? s + (target - s) * Math.min(1, dt * 6) : target;
      uniforms.uStrength.value = v;
      mesh.visible = v > 0.01;
    },
  };
}

// ------------------------------------------------------------------------------------------------ 05 splash (wave 8)
/**
 * Ref 05 splash, wave 8: the water parts round Benny's base and pours back-outward in two fans of WHITEWATER ROPES
 * lying on the surface (white, bubbly, lumpy-edged, thinning and turning translucent cyan toward their tails; outer
 * ropes ≈35° below the horizontal on screen, inner ones ≈70°), a frothy collar of fine bubbles at the roots, and a low
 * crown of droplet jets thrown up beside the body. Used only inside 05 (index.ts cross-fades it with the shared fan
 * above, which stays bit-identical in 03/04/06–10). One instanced draw, shaped and animated in the vertex shader.
 * aType: 0 = surface rope, 1 = crown droplet jet, 2 = root froth.
 */
const SEG5 = 8;
const VERT5 = /* glsl */ `
attribute vec2 aUV;      // x: 0 root .. 1 tail, y: -1..1 across
attribute vec4 aJet;     // x: side, y: across a (0 outer .. 1 inner), z: phase, w: seed
attribute float aType;
uniform float uTime;
uniform float uR;
uniform float uLen;
uniform float uStrength;
varying vec2 vUV;
varying float vSeed;
varying float vType;
varying float vLen;
varying float vTau;
#include <fog_pars_vertex>
float hs(float n) { return fract(sin(n * 91.345 + 3.17) * 43758.5453); }
vec3 ropePos(float u, float side, float a, float seed, float len) {
  // root on the waterline circle (from beside the body to its back flank), direction measured from straight back
  // roots just outside the fur's silhouette (the waterline chord uR hides under the body from the chase camera)
  #ifdef WATER05
  // W10 (?water05=1): approved splash = a wide fan of thin water threads leaving Benny's lower back and flanks
  // (straight back … ≈65° out), curling outward along their length; not two dense white "wings"
  float thR = mix(1.5, 0.35, a) + (hs(seed * 3.1) - 0.5) * 0.22;
  float phi = mix(1.1, 0.08, a) + (hs(seed * 5.7) - 0.5) * 0.34 + 0.35 * u * u;
  #else
  float thR = mix(1.4, 0.5, a) + (hs(seed * 3.1) - 0.5) * 0.18;
  float phi = mix(0.62, 0.06, a) + (hs(seed * 5.7) - 0.5) * 0.26 + 0.25 * u * u;
  #endif
  vec2 root = vec2(sin(thR), cos(thR)) * max(uR, 0.5) * (1.3 + 0.2 * hs(seed * 2.3));
  vec2 q = root + vec2(sin(phi), cos(phi)) * u * len;
  // ropes ride on the surface with small humps (whitewater, not flying jets)
  float y = 0.035 + 0.06 * hs(seed * 9.1) * sin(3.14159 * min(u * 1.6, 1.0)) * (1.0 - u);
  return vec3(side * q.x, y, q.y);
}
vec3 jetPos(float tau, float side, float a, float seed) {
  float thR = mix(1.6, 0.8, a) + (hs(seed * 3.1) - 0.5) * 0.2;
  float phi = mix(1.2, 0.45, a) + (hs(seed * 5.7) - 0.5) * 0.35;
  vec2 root = vec2(sin(thR), cos(thR)) * max(uR, 0.5) * 1.4;
  float len = (0.3 + 0.5 * hs(seed * 7.3)) * (0.55 + 0.45 * uStrength);
  vec2 q = root + vec2(sin(phi), cos(phi)) * tau * len;
  float H = (0.12 + 0.3 * hs(seed * 9.1)) * uStrength;
  return vec3(side * q.x, H * 4.0 * tau * (1.0 - tau) + 0.02, q.y);
}
void main() {
  float side = aJet.x, a = aJet.y, seed = aJet.w;
  vec3 p, tg;
  float w;
  vLen = 1.0;
  vTau = aUV.x;
  if (aType < 0.5) {
    // rope: fixed shape, breathing length; the lace texture flows along it in the fragment shader
    float len = uLen * (0.35 + 0.65 * hs(seed * 7.3)) * (0.9 + 0.1 * sin(uTime * 2.3 + seed * 20.0)) * (0.5 + 0.5 * uStrength);
    vLen = len;
    p = ropePos(aUV.x, side, a, seed, len);
    tg = ropePos(min(aUV.x + 0.04, 1.0), side, a, seed, len) - ropePos(max(aUV.x - 0.04, 0.0), side, a, seed, len);
    #ifdef WATER05
    // W10: thin threads (≈2–5 px near the camera), a little longer, so the water shows between them
    len *= 1.15;
    vLen = len;
    p = ropePos(aUV.x, side, a, seed, len);
    tg = ropePos(min(aUV.x + 0.04, 1.0), side, a, seed, len) - ropePos(max(aUV.x - 0.04, 0.0), side, a, seed, len);
    w = mix(0.015, 0.004, pow(aUV.x, 0.7)) * (0.55 + 0.7 * hs(seed * 19.1));
    #else
    w = mix(0.034, 0.008, pow(aUV.x, 0.7)) * (0.5 + 0.7 * hs(seed * 19.1));
    #endif
  } else if (aType < 1.5) {
    // crown droplet jet: the head runs root -> landing, the jet is a short chain of beads
    float rate = mix(1.6, 2.6, hs(seed * 11.3));
    float cyc = fract(aJet.z + uTime * rate);
    float tl = 0.3;
    float tau = clamp(cyc * (1.0 + tl) - (1.0 - aUV.x) * tl, 0.0, 1.0);
    vTau = tau;
    p = jetPos(tau, side, a, seed);
    tg = jetPos(min(tau + 0.03, 1.0), side, a, seed) - jetPos(max(tau - 0.03, 0.0), side, a, seed);
    w = mix(0.009, 0.018, hs(seed * 23.3));
  } else {
    // root froth: lace pads hugging the fur's silhouette at the water, from beside the body round to its back flank
    float th = mix(1.7, 0.3, a) + (hs(seed * 3.1) - 0.5) * 0.12;
    vec2 root = vec2(sin(th), cos(th)) * max(uR, 0.5) * (1.25 + 0.15 * hs(seed * 2.9));
    vec2 dir = vec2(sin(th + 0.35), cos(th + 0.35));
    float len = 0.2 + 0.18 * hs(seed * 7.3);
    vLen = len;
    vec2 q = root + dir * aUV.x * len;
    p = vec3(side * q.x, 0.06 + 0.04 * sin(3.14159 * aUV.x), q.y);
    tg = vec3(side * dir.x, 0.0, dir.y);
    w = (0.05 + 0.045 * hs(seed * 19.1)) * (1.0 - 0.35 * aUV.x);
  }
  vec4 mvPosition = modelViewMatrix * vec4(p, 1.0);
  vec2 tv = (modelViewMatrix * vec4(tg, 0.0)).xy;
  float tl2 = length(tv);
  vec2 nrm = tl2 > 1e-5 ? vec2(-tv.y, tv.x) / tl2 : vec2(0.0, 1.0);
  mvPosition.xy += nrm * aUV.y * w * (0.7 + 0.3 * uStrength);
  vUV = aUV;
  vSeed = seed;
  vType = aType;
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}
`;
const FRAG5 = /* glsl */ `
uniform float uTime;
uniform float uStrength;
varying vec2 vUV;
varying float vSeed;
varying float vType;
varying float vLen;
varying float vTau;
#include <fog_pars_fragment>
${NOISE_GLSL}
void main() {
  float ac = abs(vUV.y);
  vec3 cyan = vec3(0.45, 0.88, 1.0);
  vec3 white = vec3(1.1, 1.12, 1.16);
  vec3 blue = vec3(0.42, 0.6, 1.0);
  vec3 col;
  float alpha;
  if (vType < 0.5) {
    // whitewater rope: bubbly lace flowing back along it, lumpy edges, white root -> translucent cyan tail
    // chain of foam lumps (cells along the rope set a lumpy outline), breaking into separate blobs further out
    vec2 lp = vec2(vUV.x * vLen * 7.0 - uTime * 2.6 + vSeed * 31.0, vUV.y * 0.8 + vSeed * 7.0);
    float lc = cells(lp);
    float lump = 1.0 - smoothstep(0.25, 0.75, lc);
    float edge = 1.0 - smoothstep(0.25 + 0.6 * lump, 0.35 + 0.65 * lump, ac);
    float tail = 1.0 - smoothstep(0.55, 1.0, vUV.x);
    float brk = mix(1.0, smoothstep(0.3, 0.6, lump), smoothstep(0.2, 0.75, vUV.x));
    float hole = (1.0 - smoothstep(0.1, 0.2, cells(lp * 2.7 + 3.0))) * (1.0 - smoothstep(0.6, 1.0, ac));
    // it04: white only in the rope core, translucent cyan edges / tail, so the water shows between the strands
    alpha = edge * tail * brk * smoothstep(0.0, 0.04, vUV.x) * mix(0.9, 0.45, smoothstep(0.3, 1.0, ac + vUV.x * 0.5));
    col = mix(cyan, white, clamp(1.2 - vUV.x * 0.9 - ac * 0.9, 0.0, 1.0));
    col = mix(col, blue, hole * 0.55 * (1.0 - vUV.x));
  } else if (vType < 1.5) {
    // crown droplets: a chain of round beads, fading in off the water and out as they fall back
    // it05: small translucent water beads (cyan body, bright rim / glint), not white flakes
    vec2 bq = vec2((fract(vUV.x * 3.0 + vSeed * 7.0) - 0.5) * 2.4, vUV.y);
    float bd = length(bq);
    float bead = 1.0 - smoothstep(0.6, 0.9, bd);
    float life = smoothstep(0.0, 0.12, vTau) * (1.0 - smoothstep(0.75, 1.0, vTau));
    alpha = bead * life * (0.45 + 0.45 * smoothstep(0.3, 0.8, bd));
    col = mix(cyan, white, 0.35 + 0.6 * smoothstep(0.35, 0.8, bd));
  } else {
    // froth collar: fine bubbles (white with blue open holes), soft all round
    vec2 lp = vec2(vUV.x * vLen * 14.0 - uTime * 1.2 + vSeed * 17.0, vUV.y * 2.2 + vSeed * 5.0);
    float lc = cells(lp);
    float hole = 1.0 - smoothstep(0.1, 0.22, lc);
    float lace = 1.0 - smoothstep(0.45, 0.75, lc);
    float soft = (1.0 - smoothstep(0.4, 1.0, ac)) * smoothstep(0.0, 0.2, vUV.x) * (1.0 - smoothstep(0.6, 1.0, vUV.x));
    alpha = lace * soft * 0.9;
    col = mix(white, blue, hole * 0.7);
  }
  alpha *= uStrength;
  if (alpha < 0.02) discard;
  gl_FragColor = vec4(col, min(alpha, 1.0));
  ${FRAG_TAIL}
}
`;

/** wave 8: the 05 splash (same API as the shared fan) */
export function createRiderSplash05(quality: 'high' | 'low'): RiderSplash {
  const nRope = quality === 'high' ? 44 : 20;
  const nJet = quality === 'high' ? 40 : 16;
  const nFroth = quality === 'high' ? 16 : 8;
  const uvs = new Float32Array((SEG5 + 1) * 2 * 2);
  for (let i = 0; i <= SEG5; i++) uvs.set([i / SEG5, -1, i / SEG5, 1], i * 4);
  const idx: number[] = [];
  for (let i = 0; i < SEG5; i++) {
    const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
    idx.push(a, c, b, b, c, d);
  }
  const geo = new THREE.InstancedBufferGeometry();
  geo.setAttribute('aUV', new THREE.BufferAttribute(uvs, 2));
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array((SEG5 + 1) * 2 * 3), 3));
  geo.setIndex(idx);
  const perSide = nRope + nJet + nFroth;
  const n = perSide * 2;
  const jet = new Float32Array(n * 4);
  const typ = new Float32Array(n);
  let k = 0;
  for (const side of [-1, 1]) {
    const h = (x: number) => { const v = Math.sin(x * 127.1 + side * 311.7) * 43758.5453; return v - Math.floor(v); };
    const add = (count: number, type: number, salt: number) => {
      for (let i = 0; i < count; i++) {
        const a = Math.min(1, Math.max(0, (i + h(i * 1.7 + salt)) / count));
        typ[k] = type;
        jet[k * 4] = side;
        jet[k * 4 + 1] = a;
        jet[k * 4 + 2] = (i * 0.6180339 + h(i * 3.3 + salt) * 0.25) % 1;
        jet[k * 4 + 3] = h(i * 5.1 + 0.37 + salt);
        k++;
      }
    };
    add(nFroth, 2, 11.0);
    add(nRope, 0, 0.0);
    add(nJet, 1, 5.0);
  }
  geo.setAttribute('aJet', new THREE.InstancedBufferAttribute(jet, 4));
  geo.setAttribute('aType', new THREE.InstancedBufferAttribute(typ, 1));
  geo.instanceCount = n;
  const uniforms = withFog({ uTime: { value: 0 }, uR: { value: 0.45 }, uLen: { value: 1.55 }, uStrength: { value: 0 } });
  const mat = new THREE.ShaderMaterial({ uniforms, vertexShader: VERT5, fragmentShader: FRAG5, fog: true, transparent: true, depthWrite: false, side: THREE.DoubleSide, ...(WATER05 ? { defines: { WATER05: 1 } } : {}) });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.name = 'rider_splash05';
  mesh.frustumCulled = false;
  mesh.renderOrder = 3;
  mesh.visible = false;
  const basis = new THREE.Matrix4();
  const back = new THREE.Vector3();
  const sideV = new THREE.Vector3();
  let target = 0;
  let fed = false;
  return {
    mesh,
    uniforms,
    place(center, forward, up, radius, strength) {
      back.copy(forward).multiplyScalar(-1);
      sideV.crossVectors(up, back).normalize();
      basis.makeBasis(sideV, up, back);
      mesh.quaternion.setFromRotationMatrix(basis);
      mesh.position.copy(center);
      uniforms.uR.value = radius;
      target = strength;
      fed = true;
    },
    update(time, dt) {
      uniforms.uTime.value = time;
      if (!fed) target = 0;
      fed = false;
      const s = uniforms.uStrength.value as number;
      const v = dt > 0 ? s + (target - s) * Math.min(1, dt * 6) : target;
      uniforms.uStrength.value = v;
      mesh.visible = v > 0.01;
    },
  };
}

/**
 * Iridescent soap bubbles.
 *  - big bubbles: instanced camera-facing sphere IMPOSTORS (2 triangles each) with an analytic
 *    thin-film shader: saturated magenta/cyan film, crisp outline, tinted interior, white window
 *    highlights (ref 05). The on-screen diameter is capped (uMaxPx) and bubbles fade out close to the
 *    camera, so a bubble can never become a giant occluding sphere.
 *  - small bubbles: one THREE.Points draw of tiny ring-sprite bubbles.
 * Ride (03–10): bubbles live only at the SIDES of the stream, over the foam banks and the lower
 * walls (ref 05: ≈18 large 25–65 px + ≈25 small, none over the path or Benny). Drum A (01–02):
 * free-floating in the drum volume as before.
 * Pooled (fixed arrays, no per-frame allocation); respawned ahead when Benny passes them.
 */
import * as THREE from 'three';
import { type Course, WORLD } from '../world/course';
import { BERM_OUT } from './foam';
import { coreLateral } from './waterRibbon';
import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';

const BIG_VERT = /* glsl */ `
attribute float aSeed;
uniform float uFocal;   // pixels per unit at depth 1 (viewport height / (2 tan(fov/2)))
uniform float uMaxPx;   // cap on the on-screen diameter
uniform float uNear;    // fade-out distance from the camera
varying vec2 vP;
varying float vSeed;
varying float vFade;
varying float vPx;
#include <fog_pars_vertex>
void main() {
  vec4 c = modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
  float r = length((instanceMatrix * vec4(1.0, 0.0, 0.0, 0.0)).xyz);
  vec4 cv = viewMatrix * c;
  float depth = max(-cv.z, 0.01);
  float px = 2.0 * r * uFocal / depth;
  float k = min(1.0, uMaxPx / max(px, 1e-3));
  r *= k;
  vPx = px * k;
  vFade = smoothstep(uNear, uNear * 1.8, depth) * step(0.0005, r);
  vP = position.xy;
  vSeed = aSeed;
  vec4 mvPosition = cv + vec4(position.xy * r, 0.0, 0.0);
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}
`;
const BIG_FRAG = /* glsl */ `
uniform float uTime;
varying vec2 vP;
varying float vSeed;
varying float vFade;
varying float vPx;
#include <fog_pars_fragment>
${NOISE_GLSL}
void main() {
  float d2 = dot(vP, vP);
  if (d2 > 1.0 || vFade < 0.01) discard;
  float d = sqrt(d2);
  float z = sqrt(1.0 - d2);
  float f = 1.0 - z;                                   // 0 centre → 1 silhouette
  // swirling thin film: magenta / violet / cyan bands with a little gold (ref 05)
  float sw = vnoise(vP * 2.2 + vec2(uTime * 0.3 + vSeed * 13.0, vSeed * 7.0));
  float hue = f * 0.85 + sw * 0.75 + vP.x * 0.25 - vP.y * 0.2 + vSeed;
  vec3 film = iridescent(hue);
  film = vec3(film.r, film.g * 0.55 + 0.1, min(1.0, film.b * 1.1 + 0.1));   // less green
  film *= 0.74;                                        // stay under the tone-mapping knee: saturated
  float rim = smoothstep(0.5, 0.97, d);
  float edge = smoothstep(0.88, 0.97, d) * (1.0 - smoothstep(0.975, 1.0, d));
  // window highlights: a soft bright pane up-left, a small one down-right, sparkle dots on the rim
  vec2 q1 = (vP - vec2(-0.36, 0.42)) * vec2(2.2, 3.0);
  float hl = exp(-dot(q1, q1) * 2.2) * 1.2;
  vec2 q2 = vP - vec2(0.42, -0.45);
  hl += exp(-dot(q2, q2) * 55.0) * 0.7;
  float ang = atan(vP.y, vP.x);
  hl += smoothstep(0.8, 0.93, d) * (1.0 - smoothstep(0.95, 1.0, d)) * pow(max(0.0, sin(ang * 4.0 + vSeed * 31.0)), 30.0) * 0.9;
  // tiny bubbles: keep only the ring + one glint (no shimmering detail below ~14 px)
  float small = 1.0 - smoothstep(10.0, 22.0, vPx);
  hl *= 1.0 - 0.5 * small;
  vec3 col = film * (0.55 + 0.75 * rim) + vec3(1.0) * edge * 0.45 + vec3(1.05) * hl;
  float a = 0.14 + 0.1 * sw + rim * 0.6 + edge * 0.35 + hl;
  gl_FragColor = vec4(col, clamp(a, 0.0, 0.95) * vFade);
  ${FRAG_TAIL}
}
`;

const PT_VERT = /* glsl */ `
attribute float aSize;
attribute float aSeed;
uniform float uScale;
uniform float uMaxPx;
varying float vSeed;
varying float vPx;
#include <fog_pars_vertex>
void main() {
  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
  float px = aSize * uScale / max(-mvPosition.z, 0.01);
  gl_PointSize = aSize > 0.0 ? clamp(px, 2.0, uMaxPx) : 0.0;
  vPx = gl_PointSize;
  vSeed = aSeed;
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}
`;
const PT_FRAG = /* glsl */ `
uniform float uTime;
varying float vSeed;
varying float vPx;
#include <fog_pars_fragment>
${NOISE_GLSL}
void main() {
  vec2 c = gl_PointCoord - 0.5;
  float d = length(c) * 2.0;
  if (d > 1.0) discard;
  float ring = smoothstep(0.5, 0.85, d) * (1.0 - smoothstep(0.9, 1.0, d));
  vec3 irid = iridescent(d * 0.7 + vSeed + atan(c.y, c.x) * 0.12);
  irid = vec3(irid.r, irid.g * 0.55 + 0.1, irid.b) * 0.8;
  float hl = smoothstep(0.26, 0.0, length(c - vec2(-0.17, -0.17)));
  vec3 col = mix(vec3(1.0), irid, 0.6) * ring * 1.2 + vec3(1.0) * hl * 1.4 + irid * 0.25;
  // tiny sprites must not read as solid white dots: keep rim + glint, fade the very smallest
  float alpha = clamp(ring * 0.8 + hl + 0.12, 0.0, 1.0) * (0.35 + 0.65 * smoothstep(3.0, 8.0, vPx));
  gl_FragColor = vec4(col, alpha);
  ${FRAG_TAIL}
}
`;

interface BubbleState {
  s: number;
  pos: THREE.Vector3;
  vel: THREE.Vector3;
  size: number;
  phase: number;
  age: number;
  life: number;
}

export interface BubbleSystem {
  group: THREE.Group;
  big: THREE.InstancedMesh;
  small: THREE.Points;
  update(time: number, dt: number, focusS: number, camera: THREE.Camera, density?: number): void;
  counts: { big: number; small: number };
  /** QA: on-screen centres and diameters (px) of the bubbles currently drawn */
  qaScreen(camera: THREE.PerspectiveCamera, w: number, h: number): { big: number[][]; small: number[][] };
}

// seeded RNG: re-seeded on every respawn-all (checkpoint jump), so QA frames are deterministic
let rngState = 0x0b0b;
function rand() {
  rngState = (rngState + 0x6d2b79f5) >>> 0;
  let t = rngState;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function rnd(a: number, b: number) {
  return a + rand() * (b - a);
}

/** ride counts (visible at once in a 05-like frame) and caps, per quality tier */
const RIDE = {
  // wave 4 (user): ≈15–20 larger soap bubbles at the sides, only a few small ones; wave 7: in 05 the ref shows
  // ≈20–25 small ones near the banks (small05, 05 s-range only)
  high: { big: 19, small: 12, small05: 22 },
  low: { big: 14, small: 8, small05: 12 },
};
/** half width (NDC x) of the no-bubble lane around the projected cyan core / coin line */
const CORE_LANE = 0.19;
const CORE_N = 24;
/** ride big bubbles: target on-screen diameter range (px in the 864×1536 frame), ref 05 ≈25–65 px */
const BIG_PX: [number, number] = [25, 65];
/** max on-screen diameters (px at the capture/device resolution) */
const MAX_PX_RIDE = 66;
const MAX_PX_DRUM = 120;
const MAX_PX_SMALL = 22;

export function createBubbles(course: Course, opts: { quality: 'high' | 'low'; sStart: number }): BubbleSystem {
  const quality = opts.quality;
  const ride = RIDE[quality];
  const nBig = Math.max(ride.big, 16);
  const nSmall = quality === 'high' ? 170 : 80; // drum A keeps its fizz; the ride uses ride.small
  const group = new THREE.Group();
  group.name = 'bubbles';
  const dA = WORLD.drumA;
  const drumEnd = course.marks['02_drain'] ?? course.stage('03').s0;
  const st05 = course.stage('05');

  // ---- big (impostors) ----
  const quad = new THREE.PlaneGeometry(2, 2);
  const seeds = new Float32Array(nBig).map(() => rand());
  quad.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seeds, 1));
  const bigUniforms = withFog({ uTime: { value: 0 }, uFocal: { value: 1000 }, uMaxPx: { value: MAX_PX_RIDE }, uNear: { value: 3.2 } });
  const big = new THREE.InstancedMesh(
    quad,
    new THREE.ShaderMaterial({ uniforms: bigUniforms, vertexShader: BIG_VERT, fragmentShader: BIG_FRAG, fog: true, transparent: true, depthWrite: false }),
    nBig,
  );
  big.name = 'bubbles_big';
  big.frustumCulled = false;
  big.renderOrder = 5;
  group.add(big);

  // ---- small ----
  const sPos = new Float32Array(nSmall * 3);
  const sSize = new Float32Array(nSmall);
  const sSeed = new Float32Array(nSmall).map(() => rand());
  const pGeo = new THREE.BufferGeometry();
  pGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3).setUsage(THREE.DynamicDrawUsage));
  pGeo.setAttribute('aSize', new THREE.BufferAttribute(sSize, 1).setUsage(THREE.DynamicDrawUsage));
  pGeo.setAttribute('aSeed', new THREE.BufferAttribute(sSeed, 1));
  const ptUniforms = withFog({ uTime: { value: 0 }, uScale: { value: 600 }, uMaxPx: { value: MAX_PX_SMALL } });
  const small = new THREE.Points(
    pGeo,
    new THREE.ShaderMaterial({ uniforms: ptUniforms, vertexShader: PT_VERT, fragmentShader: PT_FRAG, fog: true, transparent: true, depthWrite: false }),
  );
  small.name = 'bubbles_small';
  small.frustumCulled = false;
  small.renderOrder = 4;
  group.add(small);

  const mk = (): BubbleState => ({ s: 0, pos: new THREE.Vector3(), vel: new THREE.Vector3(), size: 1, phase: 0, age: 0, life: 1 });
  const bigS: BubbleState[] = Array.from({ length: nBig }, mk);
  const smallS: BubbleState[] = Array.from({ length: nSmall }, mk);

  const tmp = new THREE.Vector3();
  const tmp2 = new THREE.Vector3();
  const tmp3 = new THREE.Vector3();
  /** camera basis of the current frame (screen-space placement / exclusion) */
  const view = { pos: new THREE.Vector3(), dir: new THREE.Vector3(0, 0, -1), right: new THREE.Vector3(1, 0, 0), up: new THREE.Vector3(0, 1, 0), tanV: 0.6, tanH: 0.34, inv: new THREE.Matrix4(), ok: false };
  /**
   * 1 = fine, 0 = in the no-bubble corridor (stream centre: Benny, splash, coin line), -1 = out of
   * the frame / too close to the camera. NDC from the camera basis; `r` (world radius) widens the
   * corridor so a bubble's rim never overlaps Benny either.
   */
  const allowed = (p: THREE.Vector3, r = 0): number => {
    if (!view.ok) return 1;
    const v = tmp3.copy(p).applyMatrix4(view.inv);
    const depth = -v.z;
    if (depth < 2.5) return -1;
    const xn = v.x / (depth * view.tanH), yn = v.y / (depth * view.tanV);
    if (Math.abs(xn) > 1.12 || yn < -1.12 || yn > 1.1) return -1;
    if (yn > 0.62) return 0; // upper tube / HUD: keep clear (ref 05 has none there)
    const rN = r / (depth * view.tanH);
    const corridor = yn < 0.1 ? 0.47 : 0.3;
    if (Math.abs(xn) - rN < corridor) return 0;
    // the route ahead (cyan core + coin line) winds off the screen centre in 05: keep a lane clear
    // around its projection at this screen row (the nearest coin sits at x≈640 in the 05 frame)
    if (coreN > 1 && yn <= coreY[coreN - 1] && yn >= coreY[0] - 0.4) {
      let i = 0;
      while (i < coreN - 2 && coreY[i + 1] < yn) i++;
      const t = Math.min(1, Math.max(0, (yn - coreY[i]) / Math.max(1e-4, coreY[i + 1] - coreY[i])));
      const xc = coreX[i] + (coreX[i + 1] - coreX[i]) * t;
      if (Math.abs(xn - xc) - rN < CORE_LANE) return 0;
    }
    return 1;
  };
  /** projected core line (NDC), sorted by screen y (bottom → top), rebuilt every frame in update() */
  const coreX = new Float32Array(CORE_N), coreY = new Float32Array(CORE_N);
  let coreN = 0;
  /** pixels per unit at depth 1 and the frame-height scale of the current frame (set in update) */
  let focalNow = 1000;
  let pxKNow = 1;
  const f0 = { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
  const fi = { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
  const ray = new THREE.Vector3();
  const spawn = (b: BubbleState, focusS: number, isBig: boolean, initial: boolean) => {
    b.phase = rand() * 6.28;
    b.age = initial ? rnd(0.5, 3) : 0;
    b.life = rnd(7, 15);
    if (focusS < drumEnd) {
      // Drum A volume: big bubbles floating around the drum, small ones near the water
      const th = rnd(0, Math.PI * 2);
      const r = Math.sqrt(rand()) * (dA.radius - 0.9);
      const x = dA.center.x + Math.cos(th) * r;
      const y = isBig ? rnd(dA.waterY - 0.2, dA.center.y + dA.radius * 0.7) : rnd(dA.waterY + 0.05, dA.waterY + 1.6);
      const z = rnd(dA.zBack + 0.6, dA.zDoor - 0.4);
      b.pos.set(x, y, z);
      b.s = focusS;
      b.vel.set(rnd(-0.15, 0.15), rnd(0.05, 0.25), rnd(-0.1, 0.1));
      b.size = isBig ? (rand() < 0.25 ? rnd(0.45, 0.85) : rnd(0.16, 0.42)) : rnd(0.05, 0.16);
      return;
    }
    // ---- ride: at the SIDES of the frame only (over the foam banks / outer water), never over the
    // stream corridor where Benny, his splash and the coin line are (ref 05: ≈18 large 25–65 px and
    // ≈25 small bubbles between the bank tops at y≈540 and Benny's splash at y≈1290, x at the sides).
    // Placed in SCREEN space so it holds for any camera: pick a side screen point, find where its view
    // ray meets the water, and float the bubble somewhere between the camera and that point. Size is
    // chosen from the wanted on-screen diameter at that depth. Respawns start further up the frame
    // (far, small) and grow naturally as Benny rides towards them.
    course.sample(Math.max(opts.sStart, focusS), f0);
    const side = rand() < 0.5 ? -1 : 1;
    const H = 1536;
    let D = 6;
    for (let attempt = 0; attempt < 5; attempt++) {
      const yPx = initial ? rnd(530, 1290) : rnd(530, 820);
      const yn = 1 - (2 * yPx) / H;
      const xn = side * rnd(isBig ? 0.55 : 0.5, 0.97);
      ray.copy(view.dir).addScaledVector(view.right, xn * view.tanH).addScaledVector(view.up, yn * view.tanV);
      // distance (along the view axis) to the water plane under Benny
      const den = ray.dot(f0.up);
      let Dw = den < -1e-3 ? tmp2.copy(f0.pos).sub(view.pos).dot(f0.up) / den : 40;
      Dw = Math.min(40, Math.max(3, Dw));
      D = Math.max(3.9, Dw * rnd(isBig ? 0.55 : 0.6, 0.92));
      // keep inside the tube: shorten the ray while the point is beyond the bank top
      let s = focusS;
      for (let k = 0; k < 4; k++) {
        tmp.copy(view.pos).addScaledVector(ray, D);
        s = focusS;
        for (let it = 0; it < 2; it++) {
          course.sample(Math.min(course.length, Math.max(opts.sStart, s)), fi);
          s += tmp2.copy(tmp).sub(fi.pos).dot(fi.tan);
        }
        s = Math.min(course.length - 0.3, Math.max(opts.sStart, s));
        course.sample(s, fi);
        const hw = course.widthAt(s) / 2;
        const lat = tmp2.copy(tmp).sub(fi.pos).dot(fi.right);
        if (Math.abs(lat) <= hw + BERM_OUT + 0.3) break;
        D *= 0.85;
      }
      // never under the water / inside the bank foam
